#!/usr/bin/env python3
"""Exact integer acceptance; floating point LP proposes duals and splits only.
Usage: python verify.py [72_4.txt [threads]]
Download from https://users.aalto.fi/~pat/opt/72_4.txt if passing a local first argument.
"""
import hashlib, os, pathlib, subprocess, sys, tempfile, urllib.request
from collections import Counter, defaultdict
def run():
    if not __debug__: raise RuntimeError("run this verifier without -O")
    raw = pathlib.Path(sys.argv[1]).read_bytes() if len(sys.argv)>1 else urllib.request.urlopen("https://users.aalto.fi/~pat/opt/72_4.txt").read()
    z = list(map(int, raw.split()))
    assert len(z)==7010 and z[:2]==[96,11]
    normalized=''.join(str(x)+'\n' for x in z).encode()
    assert hashlib.sha256(normalized).hexdigest()=='0f3fe74e631f11d3d3263c1c476d86ad142298ed6e2184f2b06370c771519d23'
    C=[z[3+i*73:75+i*73] for i in range(96)]
    assert all(z[2+i*73]==72 and len(set(c))==72 and all(0<=u<2048 for u in c) and min((u^v).bit_count() for u in c for v in c if u!=v)==4 for i,c in enumerate(C))
    data=''.join(' '.join(map(str,c))+'\n' for c in C)
    with tempfile.TemporaryDirectory() as base:
        wd=pathlib.Path(base)
        (wd/'C.dat').write_text(data)
        for name, source in SOURCES.items(): (wd/name).write_text(source)
        env=dict(os.environ,OMP_NUM_THREADS=sys.argv[2] if len(sys.argv)>2 else '2')
        for exe in ['two','tworad']:
            subprocess.run([os.environ.get('CXX','c++'),'-std=c++17','-O3','-fopenmp',exe+'.cpp','-o',exe],cwd=wd,check=True)
            subprocess.run([str(wd/exe)],cwd=wd,env=env,check=True)
        for name in ['two_0_96.log','tworad.tsv']:
            rows=[line.split() for line in (wd/name).read_text().splitlines()]
            assert len(rows)==96 and all(s[0]=='C' and list(map(int,s[-2:]))==[0,0] for s in rows),name
            assert sorted(int(s[1]) for s in rows)==list(range(96))
        from itertools import combinations
        tot=0; directed=0; binary_fits=0
        for code in C:
            H=defaultdict(list)
            for v in range(2048):
                B=[j for j,c in enumerate(code) if (v^c).bit_count()<4]
                assert len(B)>0
                if len(B)==1:
                    a=B[0]
                    for b in range(72):
                        if a!=b:H[min(a,b),max(a,b)].append(v)
                elif len(B)==2:H[tuple(B)].append(v)
            assert len(H)==2556
            for corners in H.values():
                binary_fits+=len(corners)
                directed+=sum((v^w).bit_count()<4 for v in corners for w in corners)
                assert not any(min((u^v).bit_count(),(v^w).bit_count(),(u^w).bit_count())>=4 for u,v,w in combinations(corners,3))
                tot+=1
        assert (tot,directed,binary_fits)==(245376,996040,563520)
        print('All 245,376 choices of two deleted sites: no three arbitrary real replacements in the cubic cell.')
SOURCES={"lp.h":"struct LP{int m,n;vector<int>B,N;vector<vector<double>>D;LP(vector<vector<double>>A,vector<double>b,vector<double>c):m(b.size()),n(c.size()),B(m),N(n+1),D(m+2,vector<double>(n+2)){for(int i=0;i<m;i++)for(int j=0;j<n;j++)D[i][j]=A[i][j];for(int i=0;i<m;i++)B[i]=n+i,D[i][n]=-1,D[i][n+1]=b[i];for(int j=0;j<n;j++)N[j]=j,D[m][j]=-c[j];N[n]=-1;D[m+1][n]=1;}void pivot(int r,int s){double inv=1/D[r][s];for(int i=0;i<m+2;i++)if(i!=r&&abs(D[i][s])>1e-14){double q=D[i][s]*inv;for(int j=0;j<n+2;j++)if(j!=s)D[i][j]-=D[r][j]*q;D[i][s]*=-inv;}for(int j=0;j<n+2;j++)if(j!=s)D[r][j]*=inv;D[r][s]=inv;swap(B[r],N[s]);}bool sp(int ph){int r0=ph==1?m+1:m;for(int lim=0;lim<2000;lim++){int s=-1;for(int j=0;j<=n;j++){if(ph==2&&N[j]==-1)continue;if(s<0||make_pair(D[r0][j],N[j])<make_pair(D[r0][s],N[s]))s=j;}if(D[r0][s]>-1e-8)return true;int r=-1;for(int i=0;i<m;i++)if(D[i][s]>1e-8){if(r<0||make_pair(D[i][n+1]/D[i][s],B[i])<make_pair(D[r][n+1]/D[r][s],B[r]))r=i;}if(r<0)return false;pivot(r,s);}return false;}double solve(vector<double>&y){int r=0;for(int i=0;i<m;i++)if(D[i][n+1]<D[r][n+1])r=i;if(D[r][n+1]<-1e-8){pivot(r,n);if(!sp(1)||D[m+1][n+1]<-1e-8)return -1e30;for(int i=0;i<m;i++)if(B[i]==-1){int s=0;for(int j=1;j<=n;j++)if(abs(D[i][j])>abs(D[i][s]))s=j;if(abs(D[i][s])>1e-8)pivot(i,s);}}if(!sp(2))return 1e30;y.assign(m,0);for(int j=0;j<=n;j++)if(N[j]>=n)y[N[j]-n]=D[m][j];return D[m][n+1];}};","b2.h":"#include <bits/stdc++.h>\n#include <omp.h>\nusing namespace std;\n#include \"lp.h\"\nconst int Q=128,T0=16*Q*Q;\nint W[2048];vector<vector<int>>C(96,vector<int>(72));\nstruct Bx{array<int,11> l{},h;Bx(){h.fill(Q);}};\nstruct Row{array<int,11>A{};int b,id;};\nint exactMask(int v,int i,int j,const array<int,11>&y,int mask,int T){int m=INT_MAX;for(int c=0;c<72;c++)if(c!=j){int d=0;for(int k=0;k<11;k++){int e=((C[i][c]^v)>>k&1)?2*Q-y[k]:y[k];d+=e*e;}m=min(m,d);}if(mask>=0){int a=0;for(int k=0;k<11;k++)if(mask>>k&1)a+=y[k]*y[k];m=min(m,T0-T*Q*Q+a);}return m;}\nstruct Solver{int skip2=-2;long long calls=0,lpN=0,blimit=12000;int dep=85;array<int,11>hit{};int rec(int i,int j,int v,int mask,int T,Bx&x,int depth){if(++calls>blimit)return 0;vector<Row> rows;for(int c=0;c<72+(mask>=0);c++)if(c!=j&&c!=skip2){Row a;a.id=c;a.b=c==72?T0-T*Q*Q:0;for(int k=0;k<11;k++){if(c==72&&!(mask>>k&1))continue;int e=c==72?0:2*Q*((v^C[i][c])>>k&1);int l=x.l[k],h=x.h[k];a.b+=(l-e)*(l-e);a.A[k]=(l+h-2*e)*(h-l);}long long mn=a.b,mx=a.b;for(int d:a.A){mn+=min(d,0);mx+=max(d,0);}if(mx<T0)return -1;if(mn<T0)rows.push_back(a);}if(rows.empty()){hit=x.l;return 1;}vector<vector<double>> A;vector<double>b;for(auto&r:rows){vector<double> aa(12);for(int k=0;k<11;k++)aa[k]=-double(r.A[k])/Q/Q;aa[11]=1;A.push_back(aa);b.push_back(double(r.b)/Q/Q);}for(int k=0;k<11;k++){vector<double>aa(12);aa[k]=1;A.push_back(aa);b.push_back(1);}vector<double>o(12),y;o[11]=1;LP lp(A,b,o);lpN++;double z=lp.solve(y);vector<long long> g(11);long long tot=0,n=0;for(int r=0;r<(int)rows.size()&&r<(int)y.size();r++){int wt=isfinite(y[r])?int(llround(clamp(y[r]*65536.,0.,16777216.))):0;n+=wt;tot+=1LL*rows[r].b*wt;for(int k=0;k<11;k++)g[k]+=1LL*rows[r].A[k]*wt;}for(long long a:g)tot+=max(a,0LL);if(n&&tot<n*T0)return -1;array<int,11>point=x.l;for(int r=0;r<lp.m;r++)if(lp.B[r]<11&&lp.B[r]>=0){int k=lp.B[r];double t=lp.D[r][lp.n+1];if(isfinite(t))point[k]=x.l[k]+int(llround((x.h[k]-x.l[k])*clamp(t,0.,1.)));}\nint exact=INT_MAX;for(int c=0;c<72;c++)if(c!=j&&c!=skip2){int d=0;for(int k=0;k<11;k++){int e=((C[i][c]^v)>>k&1)?2*Q-point[k]:point[k];d+=e*e;}exact=min(exact,d);}if(mask>=0){int a=0;for(int k=0;k<11;k++)if(mask>>k&1)a+=point[k]*point[k];exact=min(exact,T0-T*Q*Q+a);}if(exact>=T0){hit=point;return 1;}\nif(depth>=dep)return 0;double best=-1;int K=-1;\nfor(int k=0;k<11;k++){int l=x.l[k],h=x.h[k],w=h-l;if(w<2)continue;double g=(point[k]-l)*(h-point[k]);double sc=g+0.0001*w*w;if(sc>best)best=sc,K=k;}if(K<0)return 0;int l=x.l[K],h=x.h[K],mid=(l+h)/2;\nx.h[K]=mid;int a=rec(i,j,v,mask,T,x,depth+1);x.h[K]=h;if(a==1)return 1;x.l[K]=mid;int b2=rec(i,j,v,mask,T,x,depth+1);x.l[K]=l;return b2==1?1:(a<0&&b2<0?-1:0);}\n};","two.cpp":"#include \"b2.h\"\nstruct R{int up;vector<int> supp;int n,m;bool ex;};\nR bound(const vector<int>&C,int v,int d){vector<vector<double>>A;vector<double>b;vector<int>idx;for(int i=0;i<72;i++)if(i!=d){int s=C[i]^v;vector<double>row(12);for(int j=0;j<11;j++)row[j]=(s>>j&1)?3:-1;row[11]=1;A.push_back(row);b.push_back(4*W[s]);idx.push_back(i);}for(int j=0;j<11;j++){vector<double>row(12);row[j]=1;A.push_back(row);b.push_back(1);}vector<double>O(12),Y;O[11]=1;LP lp(A,b,O);double z=lp.solve(Y);vector<int>supp;long long P[11]={};long long T=0,tot=0;for(int i=0;i<(int)idx.size()&&i<(int)Y.size();i++){int q=isfinite(Y[i])?int(llround(clamp(Y[i]*1048576.,0.,16777216.))):0;if(q){int s=C[idx[i]]^v;T+=q;tot+=4LL*W[s]*q;supp.push_back(idx[i]);for(int j=0;j<11;j++)P[j]+=q*((s>>j&1)?-3:1);}}for(long long q:P)tot+=max(0LL,q);bool ex=T>0&&tot<16*T;return {(isfinite(z)?(int)llround(clamp(1000*z,-1000000.,1000000.)):0),supp,0,0,ex};}\n\nint main(int argc,char**argv){ifstream f(\"C.dat\");for(auto&a:C)for(int&i:a)f>>i;for(int v=1;v<2048;v++)W[v]=W[v&(v-1)]+1;int A=argc>1?atoi(argv[1]):0,B=argc>2?atoi(argv[2]):96;ofstream out(\"two_\"+to_string(A)+\"_\"+to_string(B)+\".log\");long long nn=0,yes=0,unknown=0,corners=0,bb=0;atomic<int>dn(0);\n#pragma omp parallel for schedule(dynamic) reduction(+:nn,yes,unknown,corners,bb)\nfor(int ii=A;ii<B;ii++){int i=(ii+64)%96;long long N=0,CN=0,U=0,Y=0;for(int v=0;v<2048;v++){vector<int> bl;for(int c=0;c<72;c++)if(W[C[i][c]^v]<4)bl.push_back(c);auto r=bound(C[i],v,-1);vector<int>s=r.supp;if(!r.ex){s.resize(72);iota(s.begin(),s.end(),0);}unsigned char seen[72][72]={};for(int j:s){auto t=bound(C[i],v,j);vector<int>u=t.supp;if(!t.ex){u.resize(72);iota(u.begin(),u.end(),0);}for(int k:u)if(k!=j){int a=min(j,k),b=max(j,k);if(seen[a][b]++)continue;bool bin=true;for(int e:bl)if(e!=a&&e!=b){bin=false;break;}if(bin){CN++;continue;}Solver solver;solver.skip2=b;solver.blimit=250;Bx x;int has=solver.rec(i,a,v,-1,0,x,0);N++;bb+=solver.calls;if(has<0)continue;U+=has==0;Y+=has>0; \n#pragma omp critical\n{out<<\"candidate \"<<i<<\" \"<<a<<\" \"<<b<<\" \"<<v<<\" \"<<has;for(int d:solver.hit)out<<\" \"<<d;out<<'\\n';}}}}\n#pragma omp critical\n{out<<\"C \"<<i<<\" \"<<N<<\" \"<<CN<<\" \"<<Y<<\" \"<<U<<\"\\n\";out.flush();int q=++dn;if(q%4==0)cerr<<\"C2 \"<<q<<\"/\"<<(B-A)<<\" Y=\"<<Y<<\" U=\"<<U<<\"\\n\";}nn+=N;yes+=Y;unknown+=U;corners+=CN;}cout<<\"TWO cuts exact masks \"<<A<<\" \"<<B<<\" nonbinTests=\"<<nn<<\" binaryFits=\"<<corners<<\" possibleNew=\"<<yes<<\" unknown=\"<<unknown<<\" box=\"<<bb<<\"\\n\";}","tworad.cpp":"#include \"b2.h\"\nint main(){ifstream f(\"C.dat\");for(auto&a:C)for(int&i:a)f>>i;for(int v=1;v<2048;v++)W[v]=W[v&(v-1)]+1;ofstream o(\"tworad.tsv\");atomic<int> dn(0);long long total=0,nn=0,uk=0,yes=0;\n#pragma omp parallel for schedule(dynamic) reduction(+:total,nn,uk,yes)\nfor(int ii=0;ii<96;ii++){int i=(ii+64)%96;map<pair<int,int>,vector<int>> H;for(int v=0;v<2048;v++){vector<int>B;for(int k=0;k<72;k++)if(W[C[i][k]^v]<4)B.push_back(k);if(B.size()==1){int j=B[0];for(int k=0;k<72;k++)if(k!=j)H[minmax(j,k)].push_back(v);}else if(B.size()==2)H[{B[0],B[1]}].push_back(v);}\nlong long a0=0,u0=0,y0=0;for(auto&[jk,Z]:H){auto[j,k]=jk;for(int v:Z)for(int w:Z){int d=W[v^w];if(d>3)continue;Solver s;s.skip2=k;s.blimit=1750;s.dep=65;Bx b;int has=s.rec(i,j,v,2047^(v^w),4-d,b,0);nn+=s.calls;a0++;if(has<0)continue;u0+=!has;y0+=has>0;\n#pragma omp critical\n{o<<i<<\" \"<<j<<\" \"<<k<<\" \"<<v<<\" \"<<w<<\" \"<<has;for(int x:s.hit)o<<\" \"<<x;o<<'\\n';}}} \n#pragma omp critical\n{o<<\"C \"<<i<<\" \"<<a0<<\" \"<<y0<<\" \"<<u0<<\"\\n\";o.flush();if(++dn%4==0)cerr<<\"r2 \"<<dn<<\" y=\"<<y0<<\" u=\"<<u0<<\"\\n\";}total+=a0;uk+=u0;yes+=y0;}\ncout<<\"pairTests \"<<total<<\" nodes \"<<nn<<\" leftovers \"<<yes<<\" unknown \"<<uk<<\"\\n\";}"}
if __name__=='__main__': run()
